   388				WHERE slug = ${runtimeConnectionIdToSlug(connectionId)}
   389				  AND organization_id = ${organizationId}
   390				  AND connector_key = 'slack'
   391				  AND external_tenant_id IS NULL
   392			`;
   393	    logger.info(
   394	      { connectionId, teamId: realTeamId },
   395	      'Backfilled teamId onto BYO Slack connection from auth.test',
   396	    );
   397	    // Only hand back the token when the confirmed team is the one being graphed;
   398	    // a token for a different workspace must not touch this team's edges.
   399	    if (realTeamId !== teamId) return null;
   400	  }
   401	
   402	  return { token, botUserId: conn.bot_user_id };
   403	}
