   453	  }
   454	  logger.info({ connections: connections.length, ok, failed }, 'Slack ACL sync tick complete');
   455	}
   100	  } catch (error) {
   101	    logger.error(
   102	      { organization_id: organizationId, connection_id: connectionId, error: String(error) },
   103	      'GitHub ACL sync failed — marking connection fail-closed',
   104	    );
