   112	function repoRefsFromFeedConfigs(configs: Array<Record<string, unknown> | null>): GithubRepoRef[] {
   113	  const seen = new Set<string>();
   114	  const refs: GithubRepoRef[] = [];
   115	  for (const config of configs) {
   116	    const owner = typeof config?.repo_owner === 'string' ? config.repo_owner.trim() : '';
   117	    const repo = typeof config?.repo_name === 'string' ? config.repo_name.trim() : '';
   118	    if (!owner || !repo) continue;
   119	    const key = `${owner}/${repo}`.toLowerCase();
   120	    if (seen.has(key)) continue;
   121	    seen.add(key);
   122	    refs.push({ owner, repo });
   123	  }
   124	  return refs;
   125	}
