   127	/** GitHub `/repos/{owner}/{repo}/collaborators`, paginated, bare `{login,id}`.
   128	 * Throws on a non-OK response so the sync treats it fail-closed. */
   129	async function fetchRepoCollaborators(
   130	  token: string,
   131	  repo: GithubRepoRef,
   132	): Promise<GithubRepoCollaborator[]> {
   133	  const collaborators: GithubRepoCollaborator[] = [];
   134	  const perPage = 100;
   135	  for (let page = 1; page <= 100; page++) {
   136	    const url = `https://api.github.com/repos/${encodeURIComponent(repo.owner)}/${encodeURIComponent(repo.repo)}/collaborators?per_page=${perPage}&page=${page}`;
   137	    const res = await fetch(url, {
   138	      headers: {
   139	        Authorization: `Bearer ${token}`,
   140	        Accept: 'application/vnd.github+json',
   141	        'User-Agent': 'lobu',
   142	        'X-GitHub-Api-Version': '2022-11-28',
   143	      },
   144	    });
   145	    if (!res.ok) {
   146	      throw new Error(`GitHub collaborators ${repo.owner}/${repo.repo} returned ${res.status}`);
   147	    }
   148	    const body = (await res.json()) as Array<{ login?: string; id?: number }>;
   149	    const items = Array.isArray(body) ? body : [];
   150	    for (const c of items) {
   151	      if (typeof c.login === 'string' && c.login) {
   152	        collaborators.push({ login: c.login, id: typeof c.id === 'number' ? c.id : undefined });
   153	      }
   154	    }
   155	    if (items.length < perPage) break;
   156	  }
   157	  return collaborators;
   158	}
