   160	/**
   161	 * The periodic production caller (registered via `./acl-sync`). Re-syncs every
   162	 * active GitHub connection's repo-membership graph so collaborator changes
   163	 * converge within the cadence and the gate's freshness window keeps a stalled
   164	 * connection fail-closed. Runs on one replica per tick (the runs-queue claim).
   165	 *
   166	 * NOTE: the live token/collaborator path needs a real GitHub App install to
   167	 * verify end to end; the sync LOGIC is covered by `__tests__/.../github-acl-sync`
   168	 * driving {@link syncGithubConnectionAcl} with stubbed deps.
   169	 */
   170	export async function runGithubAclSyncTick(coreServices: CoreServices): Promise<void> {
   171	  const sql = getDb();
   172	  const connections = await sql<{ id: string; organization_id: string }>`
   173			SELECT id::text AS id, organization_id
   174			FROM connections
   175			WHERE connector_key = 'github' AND status = 'active' AND deleted_at IS NULL
   176		`;
   177	  if (connections.length === 0) return;
   178	
   179	  const installStore = coreServices.getAppInstallationStore();
   180	
   181	  const deps: GithubAclSyncDeps = {
   182	    listRepos: async ({ connectionId }) => {
   183	      const rows = await sql<{ config: Record<string, unknown> | null }>`
   184					SELECT config FROM feeds WHERE connection_id = ${Number(connectionId)} AND deleted_at IS NULL
   185				`;
   186	      return repoRefsFromFeedConfigs(rows.map((r) => r.config));
   187	    },
   188	    fetchCollaborators: async ({ organizationId, repo }) => {
   189	      const token = await resolveGithubInstallationToken(installStore, organizationId);
   190	      if (!token) throw new Error(`No GitHub installation token for org ${organizationId}`);
   191	      return fetchRepoCollaborators(token, repo);
   192	    },
   193	  };
   194	
   195	  let ok = 0;
   196	  let failed = 0;
   197	  for (const conn of connections) {
   198	    const result = await syncGithubConnectionAcl(deps, {
   199	      connectionId: conn.id,
   200	      organizationId: conn.organization_id,
   201	    });
   202	    if (result.ok) ok += 1;
   203	    else failed += 1;
   204	  }
   205	  logger.info({ connections: connections.length, ok, failed }, 'GitHub ACL sync tick complete');
   206	}
   207	
   208	/** Resolve an org's GitHub App installation token (collaborator-capable), minted
   209	 * the same way the install flow does (`mintFor` over the install row with the
   210	 * app-id/private-key env-var names). Returns null when the org has no active
   211	 * GitHub install. */
   212	async function resolveGithubInstallationToken(
   213	  installStore: AppInstallationStore,
   214	  organizationId: string,
   215	): Promise<string | null> {
   216	  const installs = await installStore.listByProviderAndOrg('github', organizationId);
   217	  const install = installs.find((i) => i.status === 'active');
   218	  if (!install) return null;
   219	  const installWithKeys = {
   220	    ...install,
   221	    metadata: {
   222	      ...install.metadata,
   223	      appIdKey: install.metadata?.appIdKey ?? 'GITHUB_APP_ID',
   224	      privateKeyKey: install.metadata?.privateKeyKey ?? 'GITHUB_APP_PRIVATE_KEY',
   225	    },
   226	  };
   227	  const minted = await getInstallationTokenRegistry().mintFor(installWithKeys);
   228	  return minted.token;
   229	}

