 927	/**
 928	 * Resolve the SENDER of a captured chat message to an entity id — STORE-ONLY
 929	 * attribution for `channel_messages.author_entity_id`. Connector-AGNOSTIC: the
 930	 * caller hands over an already-normalized identity spec (it owns the platform's
 931	 * namespace + normalizer) and the entity type to mint on a miss; this function
 932	 * names no connector.
 933	 *
 934	 * Unlike {@link applyEventAttributions}, this writes NO event row, stamps no
 935	 * `events.metadata`, and never enters the embed pipeline: it only reads the
 936	 * normalized identity index and, on a miss, mints the given type (gated).
 937	 * Transcript is high-volume operational data, so the caller fire-and-forgets
 938	 * this — a resolution failure must never block capture or a webhook ack.
 939	 *
 940	 * Resolution (type-agnostic, driven by the #1646 cross-source collapse — a
 941	 * signed-in human is a `$member` carrying the same team-scoped chat identity):
 942	 *   1. the existing entity of ANY type owning this identity (a signed-in
 943	 *      `$member`, an already-attributed `person`, …) — return it. A single
 944	 *      {@link lookupMatches} covers all types because an identity value is
 945	 *      globally unique to one entity; no `$member`-before-`person` ordering.
 946	 *      Never mint a `$member` here (membership provisioning owns that, so
 947	 *      attribution and ACL converge on the SAME entity).
 948	 *   2. else mint `mintEntityType`, gated on a well-formed identity + a real org
 949	 *      member to attribute the create to. Callers drop bots and malformed ids
 950	 *      BEFORE calling (an empty `identities` list → null).
 951	 */
 952	export async function resolveSenderIdentity(
 953	  sql: DbClient,
 954	  params: {
 955	    orgId: string;
 956	    connectorKey: string;
 957	    mintEntityType: string;
 958	    identities: ResolvedIdentity[];
 959	    title?: string | null;
 960	  }
 961	): Promise<number | null> {
 962	  if (params.identities.length === 0) return null;
 963	
 964	  const firstHit = (matches: Map<string, number>): number | null => {
 965	    for (const id of params.identities) {
 966	      const hit = matches.get(`${id.namespace}\u0000${id.identifier}`);
 967	      if (hit !== undefined) return hit;
 968	    }
 969	    return null;
 970	  };
 971	
 972	  // 1) Any existing entity owning this identity — $member (signed-in human,
 973	  // #1646) or person, resolved by one type-agnostic lookup. No create.
 974	  const hit = firstHit(
 975	    await lookupMatches(sql, { orgId: params.orgId, identities: [params.identities] })
 976	  );
 977	  if (hit !== null) return hit;
 978	
 979	  // 2) Mint. The only remaining gate is a real org member to attribute to.
 980	  const creatorUserId = await resolveOrgCreator(params.orgId);
 981	  if (!creatorUserId) return null;
 982	
 983	  const created = await createEntityWithIdentities(sql, {
 984	    orgId: params.orgId,
 985	    connectorKey: params.connectorKey,
 986	    entityType: params.mintEntityType,
 987	    title: params.title?.trim() || '',
 988	    identities: params.identities,
 989	    traits: new Map(),
 990	    creatorUserId,
 991	  });
 992	  if (created !== null && created.attached.length > 0) {
 993	    return created.entityId;
 994	  }
 995	  // Lost the identity create-race (a concurrent ingest minted it first): drop
 996	  // the identity-less orphan and resolve to the winner instead.
 997	  if (created !== null) {
 998	    await sql`
 999	      DELETE FROM entities
1000	      WHERE id = ${created.entityId} AND organization_id = ${params.orgId}
1001	    `;
1002	    return firstHit(
1003	      await lookupMatches(sql, { orgId: params.orgId, identities: [params.identities] })
1004	    );
1005	  }
1006	  return null;
1007	}

