76	 * Resolve a Chat-SDK post target (Thread or Channel) for an outbound message.
77	 * One resolver shared by the response bridge, the interaction bridge, and the
78	 * file-upload handler.
79	 *
80	 * The dance, in order:
81	 *   1. `responseThreadId` (when given): a full thread id (e.g. a Telegram forum
82	 *      topic) — resolve it via `createThread` so the reply lands in that topic.
83	 *      A resolution failure here is non-fatal and falls through to the rest.
84	 *   2. DM shortcut: when there's no `conversationId` or it equals `channelId`,
85	 *      the conversation is channel-level — return the channel directly.
86	 *   3. Threaded: `conversationId` is the canonical `thread.id` — resolve via
87	 *      `createThread`.
88	 *   4. Last-resort channel fallback so the response still lands somewhere.
89	 *
90	 * Returns `null` only when nothing resolves.
 1	/**
 2	 * Typed view over the loose `platformMetadata: Record<string, unknown>`
 3	 * bag that rides on `ThreadResponsePayload` / `MessagePayload`. Workers
 4	 * and producers stuff various fields onto this object — historically read
 5	 * with `(metadata as any).fooBar` at every call site. That hid two real
 6	 * bugs in the guardrails wiring: the agentId fallback typed itself wrong,
 7	 * and the organizationId read assumed a string without a runtime guard.
 8	 *
 9	 * This module declares the contract and gives a single narrowing helper
10	 * so call sites can read fields without `any` and still tolerate the
11	 * absence of the field.
12	 */
13	
14	import type { BangBashCommand } from "@lobu/core";
15	
16	export interface PlatformMetadata {
17	  /** Outbound: the Chat SDK connection the response originated from. */
18	  connectionId?: string;
19	  /** Outbound: optional override for the chat-level recipient. */
20	  chatId?: string;
21	  /** Outbound: alternative override (Slack legacy ephemerals). */
22	  responseChannel?: string;
23	  /** Outbound: full thread id (e.g. `telegram:{chat}:{topic}`). */
24	  responseThreadId?: string;
25	  /** Both directions: the agent that produced/should produce the message. */
26	  agentId?: string;
27	  /** Both directions: the agent's owning organization id. */
28	  organizationId?: string;
29	  /** Inbound: chat sender's platform user id. */
30	  senderId?: string;
31	  senderUsername?: string;
32	  senderDisplayName?: string;
33	  /** Inbound: Slack workspace id (also used as `raw.team_id` shim). */
34	  teamId?: string;
35	  /**
36	   * Inbound: a link back to the originating conversation/message on the source
37	   * platform (e.g. a Slack permalink). Surfaced to the agent in its per-run
38	   * conversation context. Absent for platforms that have no addressable URL.
39	   */
40	  conversationUrl?: string;
41	  /** Outbound: marker for the session-reset signal from the worker. */
42	  sessionReset?: boolean;
43	  /**
44	   * Inbound: a `!`-bash control action. Set at ingress when the message text is
45	   * `!cmd` (run `cmd` as shell in the conversation's pinned sandbox, LLM skipped)
46	   * or `!!cmd` (same, but exclude command+output from later model context). The
47	   * worker reads this after the session-reset return and runs the command
48	   * through the hardened bash path; a bare `!`/`!!` with no command is treated
49	   * as ordinary text and never sets this.
50	   */
51	  bangBash?: BangBashCommand;
52	  /** Outbound: distributed tracing context propagation. */
53	  traceparent?: string;
54	  /** Outbound: client-side message id correlation. */
55	  clientMessageId?: string;
56	}
57	
58	/**
59	 * Read `platformMetadata` as a typed object. Always returns an object
60	 * (empty when missing) so callers can safely chain optional reads without
61	 * a null check at each site.
62	 */
63	export function readPlatformMetadata(
64	  metadata: Record<string, unknown> | null | undefined
65	): PlatformMetadata {
66	  if (!metadata || typeof metadata !== "object") return {};
67	  return metadata as PlatformMetadata;
68	}
69	
70	/**
71	 * Narrow a single string field on platformMetadata. Returns undefined when
72	 * the field is missing, empty, or the wrong type — never throws.
73	 */
74	export function platformMetadataString(
75	  metadata: Record<string, unknown> | null | undefined,
76	  key: keyof PlatformMetadata
77	): string | undefined {
78	  if (!metadata || typeof metadata !== "object") return undefined;
79	  const value = (metadata as Record<string, unknown>)[key];
80	  if (typeof value !== "string" || value.length === 0) return undefined;
81	  return value;
82	}

